```javascript
function swapAdjectives(sentence) {
  const words = sentence.split(' ');
  const adjectivePattern = /^(adjective|adjectival)\s+/; // Simple pattern, refine for complex cases if needed
  let adjectives = [];
  for (let i = 0; i < words.length; i++) {
    if (adjectivePattern.test(words[i])) {
      adjectives.push(words[i] + ' '); // Collect adjectives with spaces
    }
  }

  // Reverse the collected adjectives
  adjectives = adjectives.reverse().join(''); 

  // Reconstruct the sentence with swapped order
  const restructuredSentence = words.slice(0, words.indexOf(adjectives.trim()) ).join(' ') + adjectives.trim() + ' ' + words.slice(words.indexOf(adjectives.trim()) + 1).join(' ');
  return restructuredSentence;
}

// Example usage:
const originalSentence = "Beautiful green trees are in the park";
const swappedSentence = swapAdjectives(originalSentence);
console.log(swappedSentence); // Output: Green beautiful trees are in the park
```

