#include <iostream>
#include <limits>

using namespace std;

// Recursive Fibonacci function with error handling
int fibonacci(int a, int b, int n) {
    if (n <= 0) return 0;  // Base case: Empty sequence or invalid input
    else if (n == 1) return a; // First element
    else if (n == 2) return b; // Second element
    else {
        int result = a + fibonacci(b, a + b, n - 1); 
        return result; 
    }
}

// Utility function to ensure valid numeric input
int getValidInt(const string& prompt) {
    int input;
    while (!(cin >> input) || input < 0) {
        cout << "Invalid input. Please enter a non-negative integer: ";
        cin.clear();  // Reset error state
        cin.ignore(numeric_limits<streamsize>::max(), '\n'); // Clear input buffer
    }
    return input;
}

int main() {
    int start1, start2, count;

    cout << "Enter the first two integers for the Fibonacci sequence: ";
    start1 = getValidInt("");
    start2 = getValidInt("");

    cout << "Enter the desired number of sequence elements: ";
    count = getValidInt("");

    cout << "Fibonacci Sequence (starting with " << start1 << ", " << start2 << "): ";
    for (int i = 1; i <= count; ++i) {
        int fibElement = fibonacci(start1, start2, i);
        cout << fibElement;
        if (i < count) cout << ", "; // Separator except for the last element
        start1 = start2;         // Update for next iteration
        start2 = fibElement;      
    }
    cout << endl;

    return 0;
}
```

