    public class RestServiceClient<TResponse> where TResponse : class
    {
        private readonly string _baseUrl;
        private readonly HttpClient _httpClient;
        private readonly Func<string, string> _authTokenProvider; // Delegate for dynamic auth token retrieval

        public RestServiceClient(string baseUrl, Func<string, string> authTokenProvider)
        {
            _baseUrl = baseUrl;
            _httpClient = new HttpClient { BaseAddress = new Uri(baseUrl) };
            _authTokenProvider = authTokenProvider;
        }

        // Generic Method for Making API Calls (GET, POST, PUT, DELETE adaptable)
        public async Task<TResponse> ExecuteRequestAsync(string endpoint, HttpMethod method, object requestBody = null, string additionalHeaders = null)
        {
            var fullUrl = $"{_baseUrl}{endpoint}";
            var request = new HttpRequestMessage(method, fullUrl);

            // Dynamic Auth Token Handling
            string authToken = _authTokenProvider(fullUrl); // Fetch token based on context if needed
            request.Headers.Add("Authorization", $"Bearer {authToken}"); 

            // Add extra headers if provided
            if (!string.IsNullOrEmpty(additionalHeaders))
                request.Headers.Add(additionalHeaders);

            // Serialize request body for POST/PUT
            if (requestBody != null && (method == HttpMethod.Post || method == HttpMethod.Put))
            {
                string jsonBody = JsonConvert.SerializeObject(requestBody);
                request.Content = new StringContent(jsonBody, System.Text.Encoding.UTF8, "application/json");
            }

            HttpResponseMessage response = await _httpClient.SendAsync(request);
            response.EnsureSuccessStatusCode(); // Throw exception for bad status codes

            string content = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<TResponse>(content); 
        }

