function determineMostRelevantProtocol(inputData) {
  // **Prioritize based on weighted factors for clarity and helpfulness:**

  const ipv6Match = inputData.sourceIP && inputData.destinationIP &&  /^(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$/.test(inputData.sourceIP) && /^(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$/.test(inputData.destinationIP); // Strong IPv6 indicator
  const httpMatch = inputData.port === 80 && typeof inputData.payload === 'string'; // Common HTTP port and textual payload

  // Weighted Decision:
  if (ipv6Match && httpMatch) {  // Highest combined weight: IPv6 AND HTTP characteristics
    return { protocol: "HTTP", explanation: "Both IPv6 addresses and port 80 with textual data strongly suggest HTTP." }; 
  } else if (ipv6Match) {  //  Slight edge to IPv6 if no definitive HTTP indicators
    return { protocol: "IPv6", explanation: "Presence of IPv6 addresses makes IPv6 the most relevant." };
  } else if (httpMatch) {  //  Consider HTTP if port and payload align
    return { protocol: "HTTP", explanation: "Port 80 and string payload point towards HTTP." };
  } else {
    return { protocol: "UDP", explanation: "Without clear IPv6 or HTTP signals, UDP is a general-purpose alternative." }; 
  }
}

// Test with provided data:
const result = determineMostRelevantProtocol(inputData);
console.log(result.protocol, " - ", result.explanation); // Output: HTTP - Both IPv6 addresses and port 80 with textual data strongly suggest HTTP.
```

