import { Injectable } from '@nestjs/common';
import { CanActivate, ExecutionContext, UnauthorizedException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { PrismaService } from './prisma.service';
import { ROLE_PERMISSIONS } from './constants'; // Assuming constants file for predefined roles & permissions

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector, private prisma: PrismaService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const requiredRoles = this.reflector.get<string[]>('roles', context.getHandler());
    if (!requiredRoles) return true; // No roles restriction

    const request = context.switchToHttp().getRequest();
    const user = request.user; 
    if (!user || !user.role) throw new UnauthorizedException('User role missing');

    const userPermissions = await this.prisma.userRoles.findUnique({
      where: { userId: user.id },
      select: { permissions: true }
    });

    const allowed = requiredRoles.some(role => {
      return ROLE_PERMISSIONS[role].some(perm => userPermissions?.permissions.includes(perm));
    });

    return allowed;
  }
}

// Example usage in a controller method decorator:
// @UseGuards(RolesGuard(['ADMIN', 'EDITOR']))
// async handleAction(...) { ... }
