function geocodeAndStore(spreadsheet, sheetName, columnName, latitudeColumn, longitudeColumn) {
  // 1. Get Spreadsheet and Data Range
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(sheetName);
  const dataRange = sheet.getRange(columnName + ":L"); // Adjust 'L' if your data extends further
  const values = dataRange.getValues();

  // 2. Google Maps Geocoding API Setup (Requires API Key)
  const geocoder = new google.maps.Geocoder(); // Initialize Geocoder
  const apiKey = "YOUR_GOOGLE_MAPS_API_KEY"; //  Replace with your actual API key from Google Cloud Console

  // 3. Process Each Place Name and Geocode
  for (let row = 1; row < values.length; row++) {  // Start from row 1 (assuming headers in row 0)
    const placeName = values[row][0]; // Extract place name from the specified column
    geocoder.geocode({ address: placeName }, (results, status) => {
      if (status === google.maps.GeocoderStatus.OK) {
        const latitude = results[0].geometry.location.lat();
        const longitude = results[0].geometry.location.lng();

        // 4. Update Spreadsheet with Latitude and Longitude
        sheet.getRange(row + 1, latitudeColumn).setValue(latitude); // +1 for row offset
        sheet.getRange(row + 1, longitudeColumn).setValue(longitude);
      } else {
        Logger.log(`Geocoding Error for ${placeName}: ${status}`); // Handle errors
        // You might want to add a specific error value or marker in the spreadsheet for failed geocodes
      }
    });
  }
}
```

